-- Local-only additive streaming checkpoints. No player tables are rebuilt.
CREATE TABLE rpg_season_transfer_jobs (realm_id TEXT NOT NULL,kind TEXT NOT NULL,stage TEXT NOT NULL,cursor_json TEXT NOT NULL,rev INTEGER NOT NULL,updated_at INTEGER NOT NULL,PRIMARY KEY(realm_id,kind));
CREATE TABLE rpg_season_transfer_pages (realm_id TEXT NOT NULL,page_no INTEGER NOT NULL,page_hash TEXT NOT NULL,header_json TEXT NOT NULL,table_name TEXT NOT NULL,PRIMARY KEY(realm_id,page_no));
CREATE TABLE rpg_season_transfer_tables (realm_id TEXT NOT NULL,table_no INTEGER NOT NULL,definition_json TEXT NOT NULL,PRIMARY KEY(realm_id,table_no));
CREATE TRIGGER season_lock_rpg_accounts_insert BEFORE INSERT ON rpg_accounts WHEN EXISTS(SELECT 1 FROM rpg_season_transfer_jobs WHERE kind='seal') BEGIN SELECT RAISE(ABORT,'season_source_locked'); END;
